class PeakStack {
  private a: number[] = [];

  push(x: number): void { this.a.push(x); }
  pop(): number { return this.a.pop()!; }
  top(): number { return this.a[this.a.length - 1]; }
  peekMax(): number { return Math.max(...this.a); }

  popMax(): number {
    let at = this.a.length - 1;
    for (let i = this.a.length - 1; i >= 0; i--) if (this.a[i] > this.a[at]) at = i;
    return this.a.splice(at, 1)[0];
  }
}

