type Item = [number, number]; // [value, id]

class PeakStack {
  private stack: Item[] = [];
  private heap: Item[] = [];
  private removed = new Set<number>();
  private nextId = 0;

  // a should sit above b in the heap: larger value, then newer id
  private above(a: Item, b: Item): boolean {
    return a[0] > b[0] || (a[0] === b[0] && a[1] > b[1]);
  }

  private heapPush(it: Item): void {
    const h = this.heap;
    h.push(it);
    let i = h.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!this.above(h[i], h[p])) break;
      [h[i], h[p]] = [h[p], h[i]];
      i = p;
    }
  }

  private heapPop(): Item {
    const h = this.heap, top = h[0], last = h.pop()!;
    if (h.length) {
      h[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < h.length && this.above(h[l], h[m])) m = l;
        if (r < h.length && this.above(h[r], h[m])) m = r;
        if (m === i) break;
        [h[i], h[m]] = [h[m], h[i]];
        i = m;
      }
    }
    return top;
  }

  private cleanStack(): void {
    while (this.removed.has(this.stack[this.stack.length - 1][1])) this.removed.delete(this.stack.pop()![1]);
  }

  private cleanHeap(): void {
    while (this.removed.has(this.heap[0][1])) this.removed.delete(this.heapPop()[1]);
  }

  push(x: number): void {
    const it: Item = [x, this.nextId++];
    this.stack.push(it);
    this.heapPush(it);
  }

  pop(): number {
    this.cleanStack();
    const [v, id] = this.stack.pop()!;
    this.removed.add(id);
    return v;
  }

  top(): number {
    this.cleanStack();
    return this.stack[this.stack.length - 1][0];
  }

  peekMax(): number {
    this.cleanHeap();
    return this.heap[0][0];
  }

  popMax(): number {
    this.cleanHeap();
    const [v, id] = this.heapPop();
    this.removed.add(id);
    return v;
  }
}

